  9	namespace UI\Icons;
 10	
 11	use UI_Icon;
 12	
 13	/**
 14	 * Read-only value object for a single available icon. Holds the icon's
 15	 * ID, FA icon name, FA prefix, and whether it is a custom (application)
 16	 * icon or a standard (framework) icon. Provides a factory method to
 17	 * create the matching {@see UI_Icon} instance.
 18	 *
 19	 * @package UI
 20	 * @subpackage Icons
 21	 * @see IconCollection
 22	 */
 23	class IconInfo
 24	{
 25	    private string $id;
 26	    private string $iconName;
 27	    private string $prefix;
 28	    private bool $isCustom;
 29	
 30	    public function __construct(string $id, string $iconName, string $prefix, bool $isCustom)
 31	    {
 32	        $this->id = $id;
 33	        $this->iconName = $iconName;
 34	        $this->prefix = $prefix;
 35	        $this->isCustom = $isCustom;
 36	    }
 37	
 38	    /**
 39	     * @return string
 40	     */
 41	    public function getID() : string
 42	    {
 43	        return $this->id;
 44	    }
 45	
 46	    /**
 47	     * @return string
 48	     */
 49	    public function getIconName() : string
 50	    {
 51	        return $this->iconName;
 52	    }
 53	
 54	    /**
 55	     * @return string
 56	     */
 57	    public function getPrefix() : string
 58	    {
 59	        return $this->prefix;
 60	    }
 61	
 62	    /**
 63	     * @return bool
 64	     */
 65	    public function isCustom() : bool
 66	    {
 67	        return $this->isCustom;
 68	    }
 69	
 70	    /**
 71	     * @return bool
 72	     */
 73	    public function isStandard() : bool
 74	    {
 75	        return !$this->isCustom;
 76	    }
 77	
 78	    /**
 79	     * Creates a UI_Icon instance with this icon's type pre-configured.
 80	     *
 81	     * When the prefix is empty, {@see UI_Icon::setType()} is called with
 82	     * one argument only (matching the generated method convention). When a
 83	     * prefix is present it is passed as the second argument.
 84	     *
 85	     * @return UI_Icon
 86	     */
 87	    public function createIcon() : UI_Icon
 88	    {
 89	        $icon = new UI_Icon();
 90	
 91	        if(empty($this->prefix))
 92	        {
 93	            $icon->setType($this->iconName);
 94	        }
 95	        else
 96	        {
 97	            $icon->setType($this->iconName, $this->prefix);
 98	        }
 99	
100	        return $icon;

