 29	abstract class ApplicationTestCase extends TestCase implements ApplicationTestCaseInterface
 30	{
 31	    /**
 32	     * @var array<string,int>
 33	     */
 34	    private static array $counter = array();
 35	
 36	    /**
 37	     * Backup of $_REQUEST state from before the test.
 38	     * @var array<string,mixed>
 39	     */
 40	    private array $requestBackup = array();
 41	
 42	    protected function logHeader(string $testName): void
 43	    {
 44	        Application::logHeader(get_class($this) . ' | ' . $testName);
 45	    }
 46	
 47	    protected function createEntryID(): string
 48	    {
 49	        return 'entry' . $this->getTestCounter();
 50	    }
 51	
 52	    protected function getTestCounter(string $name = ''): int
 53	    {
 54	        if (empty($name)) {
 55	            $name = '__default';
 56	        }
 57	
 58	        if (!isset(self::$counter[$name])) {
 59	            self::$counter[$name] = 0;
 60	        }
 61	
 62	        self::$counter[$name]++;
 63	
 64	        return self::$counter[$name];
 65	    }
 66	
