 68	    {
 69	        $this->clearTransaction();
 70	        $this->disableLogging();
 71	
 72	        if($this instanceof ImageMediaTestInterface) {
 73	            $this->tearDownImageTestCase();
 74	        }
 75	
 76	        // Restore $_REQUEST to pre-test state to prevent inter-test pollution
 77	        $_REQUEST = $this->requestBackup;
 78	    }
 79	
 80	    protected function startTransaction() : void
 81	    {
 82	        DBHelper::startConditional();
 83	    }
