103	    /**
104	     * Normalises an icon ID by replacing hyphens and spaces with underscores.
105	     *
106	     * This is the canonical normalisation method used by both the runtime
107	     * registry ({@see IconCollection}) and the build-time code generator
108	     * ({@see \Application\Composer\IconBuilder\IconsReader}). Always delegate
109	     * to this method rather than repeating the inline formula.
110	     *
111	     * Example:
112	     * ```php
113	     * IconInfo::normaliseID('time-tracker');  // → 'time_tracker'
114	     * IconInfo::normaliseID('my icon name');  // → 'my_icon_name'
115	     * IconInfo::normaliseID('already_ok');    // → 'already_ok'
116	     * ```
117	     *
118	     * @param string $id Raw icon ID (may contain hyphens or spaces).
119	     * @return string Normalised icon ID with underscores only.
120	     * @since 1.0.0
121	     */
122	    public static function normaliseID(string $id) : string
123	    {
124	        return str_replace(array('-', ' '), '_', $id);
125	    }
126	
127	    /**
128	     * Returns the method name used in the icon classes, derived by
129	     * converting the underscore-separated ID to camelCase.
130	     *
131	     * Examples: `attention_required` → `attentionRequired`, `add` → `add`.
132	     *
133	     * @return string
134	     */
135	    public function getMethodName() : string
136	    {
137	        $parts = explode('_', $this->id);
138	        $methodName = array_shift($parts);
139	
140	        foreach($parts as $part)
141	        {
142	            $methodName .= ucfirst($part);
143	        }
144	
145	        return $methodName;
146	    }
147	
148	    /**
149	     * Returns the full icon name including prefix, e.g. `far:sun`.
150	     * When the prefix is empty, only the icon name is returned, e.g. `rocket`.
151	     *
152	     * @return string
153	     */
154	    public function getFullIconName() : string
155	    {
156	        if(!empty($this->prefix))
157	        {
158	            return $this->prefix . ':' . $this->iconName;
159	        }
160	
161	        return $this->iconName;
162	    }
163	}

