 5	namespace AppFrameworkTests\UI;
 6	
 7	use AppFrameworkTestClasses\ApplicationTestCase;
 8	use UI\Icons\IconCollection;
 9	use UI\Icons\IconInfo;
10	use UI_Icon;
11	
12	final class IconCollectionTest extends ApplicationTestCase
13	{
14	    // The test application's custom-icons.json defines exactly these two icons.
15	    private const CUSTOM_ICON_IDS = array('planet', 'revisionable');
16	
17	    // A framework standard icon used for positive lookups.
18	    private const STANDARD_ICON_ID = 'add';
19	
20	    protected function tearDown() : void
21	    {
22	        IconCollection::resetInstance();
23	    }
24	
25	    /**
26	     * @return IconCollection
27	     */
28	    private function collection() : IconCollection
29	    {
30	        return IconCollection::getInstance();
31	    }
32	
33	    // -------------------------------------------------------------------------
34	    // getAll()
35	    // -------------------------------------------------------------------------
36	
37	    public function test_getAll_includesFrameworkIcons() : void
38	    {
39	        $all = $this->collection()->getAll();
40	
41	        $this->assertNotEmpty($all);
42	
43	        $ids = array_map(
44	            static function(IconInfo $icon) : string { return $icon->getID(); },
45	            $all
46	        );
47	
48	        $this->assertContains(self::STANDARD_ICON_ID, $ids);
49	    }
50	
51	    public function test_getAll_includesCustomIcons() : void
52	    {
53	        $all = $this->collection()->getAll();
54	
55	        $ids = array_map(
56	            static function(IconInfo $icon) : string { return $icon->getID(); },
57	            $all
58	        );
59	
60	        foreach(self::CUSTOM_ICON_IDS as $customID)
61	        {
62	            $this->assertContains($customID, $ids,
63	                'Expected custom icon [' . $customID . '] to be present in getAll().'
64	            );
65	        }
66	    }
67	
68	    // -------------------------------------------------------------------------
69	    // getCustomIcons()
70	    // -------------------------------------------------------------------------
71	
72	    public function test_getCustomIcons_returnsExactlyCustomIcons() : void
73	    {
74	        $custom = $this->collection()->getCustomIcons();
75	
76	        $this->assertCount(count(self::CUSTOM_ICON_IDS), $custom);
77	
78	        $returnedIDs = array_map(
79	            static function(IconInfo $icon) : string { return $icon->getID(); },
80	            $custom
81	        );
82	
83	        sort($returnedIDs);
84	        $expected = self::CUSTOM_ICON_IDS;
85	        sort($expected);
86	
87	        $this->assertSame($expected, $returnedIDs);
88	    }
89	
90	    public function test_getCustomIcons_allMarkedAsCustom() : void
91	    {
92	        foreach($this->collection()->getCustomIcons() as $icon)
93	        {
94	            $this->assertTrue(
95	                $icon->isCustom(),
96	                'Icon [' . $icon->getID() . '] returned by getCustomIcons() should have isCustom() === true.'
97	            );
98	        }
99	    }

